#!/usr/bin/env node
// Generates derived files so they can never drift from their sources.
//
//   node scripts/generate.mjs           write generated files
//   node scripts/generate.mjs --check   fail (exit 1) if any generated file is stale
//
// 1. Intent patterns: shared/intent-patterns.json -> app/00-intent-patterns.js and
//    backend/app/intent_patterns.py
// 2. Service worker: sw.js SHELL is derived from index.html plus the app modules that are
//    loaded dynamically, and CACHE is a content hash of the shell, so every change to a
//    shell file produces a new cache name without a manual version bump.
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const check = process.argv.includes('--check');
const stale = [];

const read = rel => fs.readFileSync(path.join(root, rel), 'utf8');
function write(rel, content) {
  const abs = path.join(root, rel);
  const previous = fs.existsSync(abs) ? fs.readFileSync(abs, 'utf8') : null;
  if (previous === content) return;
  stale.push(rel);
  if (!check) fs.writeFileSync(abs, content);
}

// ---- 1. Intent patterns -------------------------------------------------------------
const spec = JSON.parse(read('shared/intent-patterns.json'));
const inventory = spec.inventory.map(pattern => pattern.replaceAll('TOPIC', spec.topicWords));
for (const pattern of inventory) new RegExp(pattern, 'i'); // fail fast on invalid syntax

write('app/00-intent-patterns.js', `// GENERATED by scripts/generate.mjs from shared/intent-patterns.json. Do not edit by hand.
(function (root) {
  root.NZ_INTENT = {
    inventory: [
${inventory.map(p => `      new RegExp(${JSON.stringify(p)}, 'i'),`).join('\n')}
    ],
  };
})(typeof window !== 'undefined' ? window : globalThis);
`);

write('backend/app/intent_patterns.py', `"""GENERATED by scripts/generate.mjs from shared/intent-patterns.json. Do not edit by hand."""

INVENTORY_PATTERNS = (
${inventory.map(p => `    ${JSON.stringify(p)},`).join('\n')}
)
`);

// ---- 2. Service worker shell and cache name ----------------------------------------
const fixedShell = ['./', 'index.html', 'manifest.webmanifest', 'icon-192.png', 'icon-512.png'];
const html = read('index.html');
const htmlAssets = [...html.matchAll(/(?:src|href)="([^"]+)"/g)]
  .map(match => match[1])
  .filter(url => /\.(js|css)$/.test(url) && !/^(https?:)?\/\//.test(url));

// App modules that are injected at runtime (for example 07-voice-profiles.js) are not in
// index.html, so they are discovered from string references in the app source.
const appFiles = fs.readdirSync(path.join(root, 'app')).filter(name => /^\d\d-.*\.js$/.test(name));
const referenced = new Set();
for (const name of appFiles) {
  for (const match of read(path.join('app', name)).matchAll(/app\/(\d\d-[\w-]+\.js)/g)) referenced.add(`app/${match[1]}`);
}
// 09-knowledge-index.js is deliberately not loaded (see backend/RAG_AUDIT.md) and is excluded.
const shell = [...new Set([...fixedShell, ...htmlAssets, ...referenced])].sort((a, b) => {
  const order = x => (fixedShell.includes(x) ? fixedShell.indexOf(x) : fixedShell.length);
  return order(a) - order(b) || 0;
});

const files = shell.filter(file => !file.endsWith('/')); // './' is the app root and is hashed via index.html
for (const file of files) {
  if (!fs.existsSync(path.join(root, file))) throw new Error(`Shell asset is missing: ${file}`);
}
const hash = crypto.createHash('sha256');
for (const file of files) {
  hash.update(file);
  hash.update('\0');
  hash.update(fs.readFileSync(path.join(root, file)));
}
const cacheName = `notez-${hash.digest('hex').slice(0, 12)}`;

let sw = read('sw.js');
if (!/const CACHE = '[^']*';/.test(sw) || !/const SHELL = \[[^\]]*\];/.test(sw)) {
  throw new Error('sw.js no longer has the CACHE/SHELL declarations this script rewrites.');
}
sw = sw
  .replace(/const CACHE = '[^']*';/, `const CACHE = '${cacheName}';`)
  .replace(/const SHELL = \[[^\]]*\];/, `const SHELL = ${JSON.stringify(shell).replaceAll('"', "'")};`);
write('sw.js', sw);

// ---- Report -------------------------------------------------------------------------
if (check) {
  if (stale.length) {
    console.error('Generated files are out of date. Run: node scripts/generate.mjs\n  ' + stale.join('\n  '));
    process.exit(1);
  }
  console.log(`Generated files are up to date (cache ${cacheName}, ${shell.length} shell assets).`);
} else {
  console.log(`Wrote ${stale.length ? stale.join(', ') : 'nothing new; generated files already current'} (cache ${cacheName}).`);
}
